TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]
SCALES = ["", "Thousand", "Million", "Billion"]

def three_digits_to_words(n):                      # the one reusable helper, used for every group
    parts = []
    if n >= 100:
        parts.append(ONES[n // 100])
        parts.append("Hundred")
        n %= 100
    if n >= 20:
        parts.append(TENS[n // 10])
        n %= 10
    if n > 0:
        parts.append(ONES[n])
    return " ".join(parts)

def number_to_words(num):
    if num == 0:
        return "Zero"
    groups = []
    while num > 0:
        groups.append(num % 1000)                     # peel off the next group of three digits
        num //= 1000
    words = []
    for i in range(len(groups) - 1, -1, -1):           # walk from the most significant group down
        if groups[i] == 0:
            continue
        group_words = three_digits_to_words(groups[i])   # call the same helper for every group
        if SCALES[i]:
            group_words += " " + SCALES[i]
        words.append(group_words)
    return " ".join(words)


if __name__ == "__main__":
    num = 12345
    print(number_to_words(num))

